        Debug.Log("=== DRAG DROP TEST COMPLETED ===");
    }
}

using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;

public class DragDropFixer : MonoBehaviour
{
    public static void Execute()
    {
        Debug.Log("=== FIXING DRAG DROP ISSUES ===");

        // Find all character drag sources
        CharacterDragSource[] dragSources = Object.FindObjectsOfType<CharacterDragSource>();

        foreach (CharacterDragSource source in dragSources)
        {
            // Ensure each drag source has proper event system setup
            FixDragSource(source);
        }

        // Ensure EventSystem exists and is properly configured
        EnsureEventSystem();

        Debug.Log("=== DRAG DROP FIXES APPLIED ===");
    }

    static void FixDragSource(CharacterDragSource source)
    {
        // Ensure the GameObject has a GraphicRaycaster
        Canvas canvas = source.GetComponentInParent<Canvas>();
        if (canvas != null && canvas.GetComponent<GraphicRaycaster>() == null)
        {
            canvas.gameObject.AddComponent<GraphicRaycaster>();
            Debug.Log($"Added GraphicRaycaster to canvas for {source.name}");
        }

        // Ensure the button is properly configured
        Button button = source.GetComponent<Button>();
        if (button != null)
        {
            button.interactable = true;

            // Ensure the button has proper transition settings
            if (button.transition == Selectable.Transition.None)
            {
                button.transition = Selectable.Transition.ColorTint;
            }
        }

        // Ensure the Image component exists and is raycast target
        Image image = source.GetComponent<Image>();
        if (image != null)
        {
            image.raycastTarget = true;
        }

        // Reset any stuck drag state
        if (source.isDragging)
        {
            Debug.Log($"Resetting stuck drag state for {source.name}");
            // Use reflection to access private ForceEndDrag method
            var method = typeof(CharacterDragSource).GetMethod("ForceEndDrag", 
                System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            method?.Invoke(source, null);
        }
    }

    static void EnsureEventSystem()
    {
        EventSystem eventSystem = Object.FindObjectOfType<EventSystem>();
        if (eventSystem == null)
        {
            GameObject eventSystemObj = new GameObject("EventSystem");
            eventSystemObj.AddComponent<EventSystem>();
            eventSystemObj.AddComponent<StandaloneInputModule>();
            Debug.Log("Created new EventSystem");
        }
        else
        {
            // Ensure the EventSystem is enabled
            eventSystem.enabled = true;

            // Ensure it has a StandaloneInputModule
            if (eventSystem.GetComponent<StandaloneInputModule>() == null)
            {
                eventSystem.gameObject.AddComponent<StandaloneInputModule>();
                Debug.Log("Added StandaloneInputModule to existing EventSystem");
            }
        }
    }
}

using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
using System.Collections;

public class SpecificDragTest : MonoBehaviour
{
    public static void Execute()
    {
        Debug.Log("=== SPECIFIC DRAG TEST FOR CHARACTER 1 ISSUE ===");

        // Find Character Button 1 specifically
        CharacterDragSource[] allSources = Object.FindObjectsOfType<CharacterDragSource>();
        CharacterDragSource character1Source = null;

        foreach (CharacterDragSource source in allSources)
        {
            if (source.name.Contains("CharacterButton_1"))
            {
                character1Source = source;
                break;
            }
        }

        if (character1Source == null)
        {
            Debug.LogError("Could not find CharacterButton_1!");
            return;
        }

        Debug.Log($"Found Character Button 1: {character1Source.name}");
        Debug.Log($"  - isDragging: {character1Source.isDragging}");
        Debug.Log($"  - GameObject active: {character1Source.gameObject.activeInHierarchy}");
        Debug.Log($"  - Component enabled: {character1Source.enabled}");

        // Check button component
        Button button = character1Source.GetComponent<Button>();
        if (button != null)
        {
            Debug.Log($"  - Button interactable: {button.interactable}");
            Debug.Log($"  - Button enabled: {button.enabled}");
        }

        // Check Image component
        Image image = character1Source.GetComponent<Image>();
        if (image != null)
        {
            Debug.Log($"  - Image raycastTarget: {image.raycastTarget}");
            Debug.Log($"  - Image enabled: {image.enabled}");
        }

        // Check RectTransform
        RectTransform rectTransform = character1Source.GetComponent<RectTransform>();
        if (rectTransform != null)
        {
            Debug.Log($"  - RectTransform position: {rectTransform.anchoredPosition}");
            Debug.Log($"  - RectTransform size: {rectTransform.sizeDelta}");
        }

        // Check if there are any overlapping UI elements
        CheckForOverlappingElements(character1Source);

        // Force reset this specific drag source
        if (character1Source.isDragging)
        {
            Debug.Log("Force resetting Character Button 1 drag state");
            var method = typeof(CharacterDragSource).GetMethod("ForceEndDrag", 
                System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            method?.Invoke(character1Source, null);
        }

        Debug.Log("=== SPECIFIC DRAG TEST COMPLETED ===");
    }

    static void CheckForOverlappingElements(CharacterDragSource targetSource)
    {
        RectTransform targetRect = targetSource.GetComponent<RectTransform>();
        if (targetRect == null) return;

        // Get all UI elements in the same parent
        Transform parent = targetSource.transform.parent;
        if (parent == null) return;

        Debug.Log($"Checking for overlapping elements with {targetSource.name}:");

        for (int i = 0; i < parent.childCount; i++)
        {
            Transform child = parent.GetChild(i);
            if (child == targetSource.transform) continue;

            RectTransform childRect = child.GetComponent<RectTransform>();
            if (childRect == null) continue;

            // Check if rects overlap
            Rect targetBounds = GetWorldRect(targetRect);
            Rect childBounds = GetWorldRect(childRect);

            if (targetBounds.Overlaps(childBounds))
            {
                Debug.LogWarning($"  - OVERLAP DETECTED with {child.name}");
                Debug.LogWarning($"    Target bounds: {targetBounds}");
                Debug.LogWarning($"    Child bounds: {childBounds}");
            }
        }
    }

    static Rect GetWorldRect(RectTransform rectTransform)
    {
        Vector3[] corners = new Vector3[4];
        rectTransform.GetWorldCorners(corners);

        float xMin = corners[0].x;
        float xMax = corners[2].x;
        float yMin = corners[0].y;
        float yMax = corners[2].y;

        return new Rect(xMin, yMin, xMax - xMin, yMax - yMin);
    }
}

using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
using System.Collections;

public class DragDropSequenceTest : MonoBehaviour
{
    public static void Execute()
    {
        Debug.Log("=== DRAG DROP SEQUENCE TEST ===");

        // Find all character drag sources and sort them by name
        CharacterDragSource[] allSources = Object.FindObjectsOfType<CharacterDragSource>();
        System.Array.Sort(allSources, (a, b) => a.name.CompareTo(b.name));

        Debug.Log($"Found {allSources.Length} drag sources:");
        for (int i = 0; i < allSources.Length; i++)
        {
            CharacterDragSource source = allSources[i];
            Debug.Log($"  {i}: {source.name} - isDragging: {source.isDragging}");

            // Check if this source has proper setup
            Button button = source.GetComponent<Button>();
            Image image = source.GetComponent<Image>();

            Debug.Log($"      Button: {(button != null ? $"interactable={button.interactable}" : "null")}");
            Debug.Log($"      Image: {(image != null ? $"raycastTarget={image.raycastTarget}" : "null")}");
            Debug.Log($"      CharacterPrefab: {(source.characterPrefab != null ? source.characterPrefab.name : "null")}");
            Debug.Log($"      GameManager: {(source.gameManager != null ? "found" : "null")}");

            if (source.gameManager != null)
            {
                Debug.Log($"      SetupMode: {source.gameManager.setupMode}");
                Debug.Log($"      SelectedTeam: {source.gameManager.selectedTeam}");
            }
        }

        // Test specific sequence: Character 1 -> Character 1 again
        CharacterDragSource character1 = null;
        foreach (CharacterDragSource source in allSources)
        {
            if (source.name.Contains("CharacterButton_1"))
            {
                character1 = source;
                break;
            }
        }

        if (character1 != null)
        {
            Debug.Log($"=== TESTING CHARACTER 1 SEQUENCE ===");
            Debug.Log($"Character 1 found: {character1.name}");

            // Simulate first drag attempt
            TestDragSequence(character1, "First drag attempt");

            // Wait a frame and test again
            TestDragSequence(character1, "Second drag attempt");
        }
        else
        {
            Debug.LogError("Could not find CharacterButton_1!");
        }

        Debug.Log("=== DRAG DROP SEQUENCE TEST COMPLETED ===");
    }

    static void TestDragSequence(CharacterDragSource source, string testName)
    {
        Debug.Log($"--- {testName} for {source.name} ---");

        // Check pre-conditions
        Debug.Log($"Pre-drag state:");
        Debug.Log($"  isDragging: {source.isDragging}");
        Debug.Log($"  currentlyDragging: {(CharacterDragSource.GetCurrentlyDragging() != null ? CharacterDragSource.GetCurrentlyDragging().name : "null")}");

        // Check if button is clickable
        Button button = source.GetComponent<Button>();
        if (button != null)
        {
            Debug.Log($"  button.interactable: {button.interactable}");
            Debug.Log($"  button.enabled: {button.enabled}");
        }

        // Check if image can receive raycast
        Image image = source.GetComponent<Image>();
        if (image != null)
        {
            Debug.Log($"  image.raycastTarget: {image.raycastTarget}");
            Debug.Log($"  image.enabled: {image.enabled}");
        }

        // Check game manager state
        if (source.gameManager != null)
        {
            Debug.Log($"  gameManager.setupMode: {source.gameManager.setupMode}");
        }

        // Check if there are any blocking UI elements
        CheckForBlockingElements(source);
    }

    static void CheckForBlockingElements(CharacterDragSource source)
    {
        // Get the canvas
        Canvas canvas = source.GetComponentInParent<Canvas>();
        if (canvas == null) return;

        // Get the GraphicRaycaster
        GraphicRaycaster raycaster = canvas.GetComponent<GraphicRaycaster>();
        if (raycaster == null) return;

        // Get the center point of the source
        RectTransform rectTransform = source.GetComponent<RectTransform>();
        if (rectTransform == null) return;

        Vector2 screenPoint = RectTransformUtility.WorldToScreenPoint(null, rectTransform.position);

        // Create pointer event data
        PointerEventData eventData = new PointerEventData(EventSystem.current);
        eventData.position = screenPoint;

        // Raycast
        var results = new System.Collections.Generic.List<RaycastResult>();
        raycaster.Raycast(eventData, results);

        Debug.Log($"Raycast results for {source.name} at {screenPoint}:");
        for (int i = 0; i < results.Count; i++)
        {
            RaycastResult result = results[i];
            Debug.Log($"  {i}: {result.gameObject.name} (distance: {result.distance})");

            if (i == 0 && result.gameObject != source.gameObject)
            {
                Debug.LogWarning($"  WARNING: First hit is not the source itself! It's {result.gameObject.name}");
            }
        }
    }
}

