using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using UnityEngine.InputSystem;

public class FixInputSystem : MonoBehaviour
{
    public static void Execute()
    {
        Debug.Log("=== FIXING INPUT SYSTEM ===");

        // Check EventSystem
        EventSystem eventSystem = Object.FindObjectOfType<EventSystem>();
        if (eventSystem == null)
        {
            Debug.LogError("No EventSystem found! Creating one...");
            GameObject eventSystemObj = new GameObject("EventSystem");
            eventSystem = eventSystemObj.AddComponent<EventSystem>();
        }

        Debug.Log($"EventSystem found: {eventSystem.name}");
        Debug.Log($"EventSystem enabled: {eventSystem.enabled}");

        // Check input modules
        var inputModules = eventSystem.GetComponents<BaseInputModule>();
        Debug.Log($"Found {inputModules.Length} input modules:");

        foreach (var module in inputModules)
        {
            Debug.Log($"  - {module.GetType().Name}: enabled={module.enabled}");
        }

        // Remove conflicting modules
        var standaloneModules = eventSystem.GetComponents<StandaloneInputModule>();
        foreach (var module in standaloneModules)
        {
            Debug.Log($"Removing StandaloneInputModule: {module.name}");
            Object.DestroyImmediate(module);
        }

        // Ensure we have InputSystemUIInputModule
        var inputSystemModule = eventSystem.GetComponent<UnityEngine.InputSystem.UI.InputSystemUIInputModule>();
        if (inputSystemModule == null)
        {
            Debug.Log("Adding InputSystemUIInputModule...");
            inputSystemModule = eventSystem.gameObject.AddComponent<UnityEngine.InputSystem.UI.InputSystemUIInputModule>();
        }

        inputSystemModule.enabled = true;
        Debug.Log($"InputSystemUIInputModule enabled: {inputSystemModule.enabled}");

        // Check Canvas and GraphicRaycaster
        Canvas[] canvases = Object.FindObjectsOfType<Canvas>();
        Debug.Log($"Found {canvases.Length} canvases:");

        foreach (Canvas canvas in canvases)
        {
            Debug.Log($"  Canvas: {canvas.name}");

            GraphicRaycaster raycaster = canvas.GetComponent<GraphicRaycaster>();
            if (raycaster == null)
            {
                Debug.Log($"    Adding GraphicRaycaster to {canvas.name}");
                raycaster = canvas.gameObject.AddComponent<GraphicRaycaster>();
            }

            raycaster.enabled = true;
            Debug.Log($"    GraphicRaycaster enabled: {raycaster.enabled}");
        }

        // Test button interactivity
        Button[] buttons = Object.FindObjectsOfType<Button>();
        Debug.Log($"Found {buttons.Length} buttons:");

        foreach (Button button in buttons)
        {
            Debug.Log($"  Button: {button.name} - interactable: {button.interactable}");

            // Ensure button is interactable
            button.interactable = true;

            // Check if button has proper target graphic
            if (button.targetGraphic == null)
            {
                Image image = button.GetComponent<Image>();
                if (image != null)
                {
                    button.targetGraphic = image;
                    Debug.Log($"    Set targetGraphic for {button.name}");
                }
            }
        }

        // Test mouse input
        Debug.Log("Testing mouse input...");
        var mouse = Mouse.current;
        if (mouse != null)
        {
            Debug.Log($"Mouse found: {mouse.name}");
            Debug.Log($"Mouse position: {mouse.position.ReadValue()}");
            Debug.Log($"Left button pressed: {mouse.leftButton.isPressed}");
        }
        else
        {
            Debug.LogError("No mouse input device found!");
        }

        // Force refresh EventSystem
        eventSystem.enabled = false;
        eventSystem.enabled = true;

        Debug.Log("=== INPUT SYSTEM FIX COMPLETED ===");
        Debug.Log("Try clicking UI elements now!");
    }
}

using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;

public class TestUIClick : MonoBehaviour
{
    public static void Execute()
    {
        Debug.Log("=== TESTING UI CLICK FUNCTIONALITY ===");

        // Test each button
        Button[] buttons = Object.FindObjectsOfType<Button>();

        foreach (Button button in buttons)
        {
            TestButton(button);
        }

        // Test EventSystem raycast
        TestEventSystemRaycast();

        Debug.Log("=== UI CLICK TEST COMPLETED ===");
        Debug.Log("If you still can't click UI, try entering Play Mode first.");
    }

    static void TestButton(Button button)
    {
        Debug.Log($"Testing button: {button.name}");

        // Check if button is active and enabled
        if (!button.gameObject.activeInHierarchy)
        {
            Debug.LogError($"  ✗ Button {button.name} is not active in hierarchy");
            return;
        }

        if (!button.enabled)
        {
            Debug.LogError($"  ✗ Button {button.name} component is disabled");
            return;
        }

        if (!button.interactable)
        {
            Debug.LogError($"  ✗ Button {button.name} is not interactable");
            return;
        }

        // Check target graphic
        if (button.targetGraphic == null)
        {
            Debug.LogWarning($"  ⚠ Button {button.name} has no target graphic");

            // Try to set it
            Image image = button.GetComponent<Image>();
            if (image != null)
            {
                button.targetGraphic = image;
                Debug.Log($"    Set target graphic to Image component");
            }
        }
        else
        {
            Debug.Log($"  ✓ Button {button.name} has target graphic: {button.targetGraphic.name}");
        }

        // Check if target graphic can receive raycast
        if (button.targetGraphic != null)
        {
            Graphic graphic = button.targetGraphic;
            if (!graphic.raycastTarget)
            {
                Debug.LogWarning($"  ⚠ Target graphic {graphic.name} has raycastTarget disabled");
                graphic.raycastTarget = true;
                Debug.Log($"    Enabled raycastTarget for {graphic.name}");
            }
            else
            {
                Debug.Log($"  ✓ Target graphic can receive raycast");
            }
        }

        // Check Canvas and GraphicRaycaster
        Canvas canvas = button.GetComponentInParent<Canvas>();
        if (canvas == null)
        {
            Debug.LogError($"  ✗ Button {button.name} is not under a Canvas");
            return;
        }

        GraphicRaycaster raycaster = canvas.GetComponent<GraphicRaycaster>();
        if (raycaster == null)
        {
            Debug.LogError($"  ✗ Canvas {canvas.name} has no GraphicRaycaster");
            return;
        }

        if (!raycaster.enabled)
        {
            Debug.LogError($"  ✗ GraphicRaycaster on {canvas.name} is disabled");
            raycaster.enabled = true;
            Debug.Log($"    Enabled GraphicRaycaster");
        }

        Debug.Log($"  ✓ Button {button.name} should be clickable");

        // Add test click listener if not already present
        if (button.onClick.GetPersistentEventCount() == 0)
        {
            button.onClick.AddListener(() => {
                Debug.Log($"Button {button.name} was clicked!");
            });
            Debug.Log($"    Added test click listener");
        }
    }

    static void TestEventSystemRaycast()
    {
        Debug.Log("Testing EventSystem raycast...");

        EventSystem eventSystem = Object.FindObjectOfType<EventSystem>();
        if (eventSystem == null)
        {
            Debug.LogError("  ✗ No EventSystem found");
            return;
        }

        if (!eventSystem.enabled)
        {
            Debug.LogError("  ✗ EventSystem is disabled");
            eventSystem.enabled = true;
            Debug.Log("    Enabled EventSystem");
        }

        // Check input module
        var inputModule = eventSystem.currentInputModule;
        if (inputModule == null)
        {
            Debug.LogError("  ✗ No input module found");
            return;
        }

        Debug.Log($"  ✓ Current input module: {inputModule.GetType().Name}");
        Debug.Log($"  ✓ Input module enabled: {inputModule.enabled}");

        // Test raycast at screen center
        Vector2 screenCenter = new Vector2(Screen.width / 2f, Screen.height / 2f);
        PointerEventData eventData = new PointerEventData(eventSystem);
        eventData.position = screenCenter;

        var results = new System.Collections.Generic.List<RaycastResult>();
        eventSystem.RaycastAll(eventData, results);

        Debug.Log($"  Raycast at screen center ({screenCenter}) found {results.Count} hits:");
        for (int i = 0; i < Mathf.Min(results.Count, 5); i++)
        {
            Debug.Log($"    {i}: {results[i].gameObject.name}");
        }
    }
}

