using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using UnityEngine.InputSystem;

public class CompleteInputSystemFix : MonoBehaviour
{
    public static void Execute()
    {
        Debug.Log("=== COMPLETE INPUT SYSTEM FIX ===");

        // Step 1: Fix EventSystem
        FixEventSystem();

        // Step 2: Fix Canvas and GraphicRaycaster
        FixCanvasRaycasting();

        // Step 3: Fix Button configurations
        FixButtonConfigurations();

        // Step 4: Test input system
        TestInputSystem();

        Debug.Log("=== INPUT SYSTEM FIX COMPLETED ===");
        Debug.Log("UI should now be clickable!");
    }

    static void FixEventSystem()
    {
        Debug.Log("Fixing EventSystem...");

        EventSystem eventSystem = Object.FindObjectOfType<EventSystem>();
        if (eventSystem == null)
        {
            GameObject eventSystemObj = new GameObject("EventSystem");
            eventSystem = eventSystemObj.AddComponent<EventSystem>();
            Debug.Log("Created new EventSystem");
        }

        // Remove old input modules
        StandaloneInputModule[] oldModules = eventSystem.GetComponents<StandaloneInputModule>();
        foreach (var module in oldModules)
        {
            Object.DestroyImmediate(module);
            Debug.Log("Removed StandaloneInputModule");
        }

        // Ensure we have InputSystemUIInputModule
        var inputModule = eventSystem.GetComponent<UnityEngine.InputSystem.UI.InputSystemUIInputModule>();
        if (inputModule == null)
        {
            inputModule = eventSystem.gameObject.AddComponent<UnityEngine.InputSystem.UI.InputSystemUIInputModule>();
            Debug.Log("Added InputSystemUIInputModule");
        }

        // Configure the input module
        inputModule.enabled = true;
        inputModule.deselectOnBackgroundClick = true;

        // Enable EventSystem
        eventSystem.enabled = true;

        Debug.Log($"EventSystem configured: {eventSystem.name}");
    }

    static void FixCanvasRaycasting()
    {
        Debug.Log("Fixing Canvas raycasting...");

        Canvas[] canvases = Object.FindObjectsOfType<Canvas>();
        foreach (Canvas canvas in canvases)
        {
            // Ensure GraphicRaycaster exists
            GraphicRaycaster raycaster = canvas.GetComponent<GraphicRaycaster>();
            if (raycaster == null)
            {
                raycaster = canvas.gameObject.AddComponent<GraphicRaycaster>();
                Debug.Log($"Added GraphicRaycaster to {canvas.name}");
            }

            // Configure GraphicRaycaster
            raycaster.enabled = true;
            raycaster.ignoreReversedGraphics = true;
            raycaster.blockingObjects = GraphicRaycaster.BlockingObjects.None;

            Debug.Log($"Canvas {canvas.name} configured for raycasting");
        }
    }

    static void FixButtonConfigurations()
    {
        Debug.Log("Fixing button configurations...");

        Button[] buttons = Object.FindObjectsOfType<Button>();
        foreach (Button button in buttons)
        {
            // Enable button
            button.enabled = true;
            button.interactable = true;

            // Ensure target graphic is set
            if (button.targetGraphic == null)
            {
                Image image = button.GetComponent<Image>();
                if (image != null)
                {
                    button.targetGraphic = image;
                    Debug.Log($"Set target graphic for {button.name}");
                }
            }

            // Ensure target graphic can receive raycast
            if (button.targetGraphic != null)
            {
                button.targetGraphic.raycastTarget = true;
            }

            // Add test click listener if none exists
            if (button.onClick.GetPersistentEventCount() == 0)
            {
                button.onClick.RemoveAllListeners();
                button.onClick.AddListener(() => {
                    Debug.Log($"[UI CLICK] Button {button.name} clicked!");
                });
            }

            Debug.Log($"Button {button.name} configured");
        }
    }

    static void TestInputSystem()
    {
        Debug.Log("Testing input system...");

        // Test mouse input
        var mouse = Mouse.current;
        if (mouse != null)
        {
            Debug.Log($"Mouse device found: {mouse.name}");
            Debug.Log($"Mouse enabled: {mouse.enabled}");
        }
        else
        {
            Debug.LogError("No mouse device found!");
        }

        // Test EventSystem
        EventSystem eventSystem = Object.FindObjectOfType<EventSystem>();
        if (eventSystem != null)
        {
            Debug.Log($"EventSystem active: {eventSystem.enabled}");
            Debug.Log($"Current input module: {eventSystem.currentInputModule?.GetType().Name}");
        }

        // Test raycast at screen center
        if (eventSystem != null)
        {
            Vector2 screenCenter = new Vector2(Screen.width / 2f, Screen.height / 2f);
            PointerEventData eventData = new PointerEventData(eventSystem);
            eventData.position = screenCenter;

            var results = new System.Collections.Generic.List<RaycastResult>();
            eventSystem.RaycastAll(eventData, results);

            Debug.Log($"Raycast test at screen center found {results.Count} UI elements");
            for (int i = 0; i < Mathf.Min(results.Count, 3); i++)
            {
                Debug.Log($"  {i}: {results[i].gameObject.name}");
            }
        }
    }
}

using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using UnityEngine.InputSystem;

public class PlayModeUITest : MonoBehaviour
{
    void Start()
    {
        // Test UI in play mode
        Invoke("TestUIInPlayMode", 1f);
    }

    void TestUIInPlayMode()
    {
        Debug.Log("=== TESTING UI IN PLAY MODE ===");

        // Test EventSystem
        EventSystem eventSystem = FindObjectOfType<EventSystem>();
        if (eventSystem != null)
        {
            Debug.Log($"EventSystem found: {eventSystem.name}");
            Debug.Log($"EventSystem enabled: {eventSystem.enabled}");
            Debug.Log($"Current input module: {eventSystem.currentInputModule?.GetType().Name}");

            if (eventSystem.currentInputModule != null)
            {
                Debug.Log($"Input module enabled: {eventSystem.currentInputModule.enabled}");
            }
        }
        else
        {
            Debug.LogError("No EventSystem found!");
        }

        // Test mouse input
        var mouse = Mouse.current;
        if (mouse != null)
        {
            Debug.Log($"Mouse found: {mouse.name}");
            Debug.Log($"Mouse position: {mouse.position.ReadValue()}");
        }
        else
        {
            Debug.LogError("No mouse found!");
        }

        // Test buttons
        Button[] buttons = FindObjectsOfType<Button>();
        Debug.Log($"Found {buttons.Length} buttons");

        foreach (Button button in buttons)
        {
            if (button.name.Contains("Character"))
            {
                Debug.Log($"Character button: {button.name} - interactable: {button.interactable}");

                // Add click listener for testing
                button.onClick.RemoveAllListeners();
                button.onClick.AddListener(() => {
                    Debug.Log($"[PLAY MODE] Button {button.name} clicked successfully!");
                });
            }
        }

        Debug.Log("=== UI TEST COMPLETED ===");
        Debug.Log("Try clicking the character buttons now!");
    }

    void Update()
    {
        // Monitor mouse clicks
        var mouse = Mouse.current;
        if (mouse != null && mouse.leftButton.wasPressedThisFrame)
        {
            Vector2 mousePos = mouse.position.ReadValue();
            Debug.Log($"Mouse clicked at: {mousePos}");

            // Test raycast
            EventSystem eventSystem = FindObjectOfType<EventSystem>();
            if (eventSystem != null)
            {
                PointerEventData eventData = new PointerEventData(eventSystem);
                eventData.position = mousePos;

                var results = new System.Collections.Generic.List<RaycastResult>();
                eventSystem.RaycastAll(eventData, results);

                Debug.Log($"Raycast found {results.Count} UI elements:");
                for (int i = 0; i < Mathf.Min(results.Count, 3); i++)
                {
                    Debug.Log($"  {i}: {results[i].gameObject.name}");
                }
            }
        }
    }
}

using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using UnityEngine.InputSystem;

public class FinalUIInputFix : MonoBehaviour
{
    public static void Execute()
    {
        Debug.Log("=== FINAL UI INPUT FIX ===");

        // Step 1: Remove DragDropDebugger to avoid conflicts
        RemoveDebugger();

        // Step 2: Completely rebuild EventSystem
        RebuildEventSystem();

        // Step 3: Fix all UI elements
        FixAllUIElements();

        // Step 4: Test everything
        TestEverything();

        Debug.Log("=== FINAL UI INPUT FIX COMPLETED ===");
        Debug.Log("UI should now be fully functional!");
    }

    static void RemoveDebugger()
    {
        DragDropDebugger debugger = Object.FindObjectOfType<DragDropDebugger>();
        if (debugger != null)
        {
            Object.DestroyImmediate(debugger);
            Debug.Log("Removed DragDropDebugger to avoid conflicts");
        }
    }

    static void RebuildEventSystem()
    {
        Debug.Log("Rebuilding EventSystem...");

        // Remove existing EventSystem
        EventSystem[] existingSystems = Object.FindObjectsOfType<EventSystem>();
        foreach (EventSystem system in existingSystems)
        {
            Object.DestroyImmediate(system.gameObject);
        }

        // Create new EventSystem
        GameObject eventSystemObj = new GameObject("EventSystem");
        EventSystem eventSystem = eventSystemObj.AddComponent<EventSystem>();

        // Add InputSystemUIInputModule
        var inputModule = eventSystemObj.AddComponent<UnityEngine.InputSystem.UI.InputSystemUIInputModule>();

        // Configure EventSystem
        eventSystem.sendNavigationEvents = true;
        eventSystem.dragThreshold = 10;

        // Configure InputModule
        inputModule.deselectOnBackgroundClick = true;
        inputModule.pointerBehavior = UnityEngine.InputSystem.UI.UIPointerBehavior.SingleMouseOrPenButMultiTouchAndTrack;

        Debug.Log("EventSystem rebuilt successfully");
    }

    static void FixAllUIElements()
    {
        Debug.Log("Fixing all UI elements...");

        // Fix Canvas
        Canvas[] canvases = Object.FindObjectsOfType<Canvas>();
        foreach (Canvas canvas in canvases)
        {
            // Ensure GraphicRaycaster
            GraphicRaycaster raycaster = canvas.GetComponent<GraphicRaycaster>();
            if (raycaster == null)
            {
                raycaster = canvas.gameObject.AddComponent<GraphicRaycaster>();
            }

            raycaster.enabled = true;
            raycaster.ignoreReversedGraphics = true;
            raycaster.blockingObjects = GraphicRaycaster.BlockingObjects.None;

            Debug.Log($"Fixed canvas: {canvas.name}");
        }

        // Fix all buttons
        Button[] buttons = Object.FindObjectsOfType<Button>();
        foreach (Button button in buttons)
        {
            // Enable button
            button.enabled = true;
            button.interactable = true;

            // Fix target graphic
            if (button.targetGraphic == null)
            {
                Image image = button.GetComponent<Image>();
                if (image != null)
                {
                    button.targetGraphic = image;
                }
            }

            // Ensure target graphic can receive raycast
            if (button.targetGraphic != null)
            {
                button.targetGraphic.raycastTarget = true;
            }

            // Clear and add test listeners
            button.onClick.RemoveAllListeners();
            string buttonName = button.name;
            button.onClick.AddListener(() => {
                Debug.Log($"[UI SUCCESS] Button '{buttonName}' clicked!");
            });

            Debug.Log($"Fixed button: {button.name}");
        }

        // Fix all child UI elements that might block raycast
        Text[] texts = Object.FindObjectsOfType<Text>();
        foreach (Text text in texts)
        {
            // Disable raycast for text elements that are children of buttons
            Button parentButton = text.GetComponentInParent<Button>();
            if (parentButton != null && text.gameObject != parentButton.gameObject)
            {
                text.raycastTarget = false;
                Debug.Log($"Disabled raycast for text: {text.name}");
            }
        }

        // Fix all child images that might block raycast
        Image[] images = Object.FindObjectsOfType<Image>();
        foreach (Image image in images)
        {
            Button parentButton = image.GetComponentInParent<Button>();
            if (parentButton != null && image.gameObject != parentButton.gameObject)
            {
                // Only disable raycast for decorative images
                if (image.name.Contains("Preview") || image.name.Contains("Border") || image.name.Contains("Icon"))
                {
                    image.raycastTarget = false;
                    Debug.Log($"Disabled raycast for image: {image.name}");
                }
            }
        }
    }

    static void TestEverything()
    {
        Debug.Log("Testing everything...");

        // Test EventSystem
        EventSystem eventSystem = Object.FindObjectOfType<EventSystem>();
        if (eventSystem != null)
        {
            Debug.Log($"✓ EventSystem found and enabled: {eventSystem.enabled}");
            Debug.Log($"✓ Input module: {eventSystem.currentInputModule?.GetType().Name}");
        }
        else
        {
            Debug.LogError("✗ No EventSystem found!");
        }

        // Test Input System
        var mouse = Mouse.current;
        if (mouse != null)
        {
            Debug.Log($"✓ Mouse input available: {mouse.name}");
        }
        else
        {
            Debug.LogError("✗ No mouse input found!");
        }

        // Test Canvas raycasting
        Canvas[] canvases = Object.FindObjectsOfType<Canvas>();
        foreach (Canvas canvas in canvases)
        {
            GraphicRaycaster raycaster = canvas.GetComponent<GraphicRaycaster>();
            if (raycaster != null && raycaster.enabled)
            {
                Debug.Log($"✓ Canvas {canvas.name} has working GraphicRaycaster");
            }
            else
            {
                Debug.LogError($"✗ Canvas {canvas.name} has no working GraphicRaycaster");
            }
        }

        // Test buttons
        Button[] buttons = Object.FindObjectsOfType<Button>();
        int workingButtons = 0;
        foreach (Button button in buttons)
        {
            if (button.enabled && button.interactable && button.targetGraphic != null && button.targetGraphic.raycastTarget)
            {
                workingButtons++;
            }
        }

        Debug.Log($"✓ {workingButtons}/{buttons.Length} buttons are properly configured");

        // Final test - simulate raycast
        if (eventSystem != null)
        {
            Vector2 screenCenter = new Vector2(Screen.width / 2f, Screen.height / 2f);
            PointerEventData eventData = new PointerEventData(eventSystem);
            eventData.position = screenCenter;

            var results = new System.Collections.Generic.List<RaycastResult>();
            eventSystem.RaycastAll(eventData, results);

            Debug.Log($"✓ Raycast test found {results.Count} UI elements at screen center");
        }
    }
}
